import java.util.Scanner;
import java.util.InputMismatchException;

public class Main {

    public static void main(String[] args) {

        Scanner teclado = new Scanner(System.in);
        TorreGT torre = new TorreGT();
        Registro registro = torre.getRegistro();

        // Carga del comienzo
        // Tres oficinas y dos dispositivos de cada tipo

        Oficina oficina1 = new Oficina("OF001", "Empresa Alfa");
        Oficina oficina2 = new Oficina("OF002", "Empresa Beta");
        Oficina oficina3 = new Oficina("OF003", "Empresa Gamma");

        registro.registrarOficina(oficina1);
        registro.registrarOficina(oficina2);
        registro.registrarOficina(oficina3);

        // Luminarias
        registro.registrarDispositivo(new Luminaria("L001", oficina1, 200));
        registro.registrarDispositivo(new Luminaria("L002", oficina2, 150));

        // Climatizadores
        registro.registrarDispositivo(new Climatizador("C001", oficina1, 1500));
        registro.registrarDispositivo(new Climatizador("C002", oficina3, 1200));

        // Climatizadores Inverter
        registro.registrarDispositivo(new ClimatizadorInverter("I001", oficina2, 1500));
        registro.registrarDispositivo(new ClimatizadorInverter("I002", oficina3, 1800));

        // Sensores de humo
        registro.registrarDispositivo(new SensorHumo("S001", oficina1, 15));
        registro.registrarDispositivo(new SensorHumo("S002", oficina2, 20));

        // Camaras de seguridad
        registro.registrarDispositivo(new CamaraSeguridad("CAM001", oficina1, 80));
        registro.registrarDispositivo(new CamaraSeguridad("CAM002", oficina3, 100));


        // Menu
        boolean continuar = true;

        while (continuar) {

            System.out.println("\nSistema TprreGT");
            System.out.println("Hora de simulacion: " + torre.getHoraSimulacion());
            System.out.println("Hora del dia: " + (torre.getHoraSimulacion() % 24) + ":00");
            System.out.println("\n1. Registrar oficina");
            System.out.println("2. Registrar dispositivo");
            System.out.println("3. Encender dispositivo");
            System.out.println("4. Apagar dispositivo");
            System.out.println("5. Ajustar nivel");
            System.out.println("6. Registrar lectura");
            System.out.println("7. Registrar movimiento");
            System.out.println("8. Avanzar una hora");
            System.out.println("9. Atender alerta");
            System.out.println("10. Consultar oficinas");
            System.out.println("11. Consultar dispositivo");
            System.out.println("12. Reporte de dispositivos por oficina");
            System.out.println("13. Reporte de alertas");
            System.out.println("14. Reporte de facturas");
            System.out.println("15. Salir");

            int opcion = 0;
            boolean opcionValida = false;

            // Opcion valida
            while (!opcionValida) {

                try {
                    System.out.print("\nSeleccione una opcion: ");
                    opcion = teclado.nextInt();
                    teclado.nextLine();

                    if (opcion >= 1 && opcion <= 15) {
                        opcionValida = true;
                    }
                    else {
                        System.out.println("Seleccione una opcion entre 1 y 15.");
                    }

                } catch (InputMismatchException e) {
                    System.out.println("Entrada invalida. Ingrese un numero.");
                    teclado.nextLine();
                }
            }


            switch (opcion) {

                // Registrar oficina
                case 1: {

                    System.out.println("\nRegistrar Oficina");

                    System.out.print("Codigo de oficina: ");
                    String codigo = teclado.nextLine();

                    if (codigo.isEmpty()) {
                        System.out.println("El codigo no puede estar vacio.");
                        break;
                    }

                    System.out.print("Nombre del inquilino: ");
                    String inquilino = teclado.nextLine();

                    if (inquilino.isEmpty()) {
                        System.out.println("El inquilino no puede estar vacio.");
                        break;
                    }

                    Oficina oficina = new Oficina(codigo, inquilino);

                    if (registro.registrarOficina(oficina)) {
                        System.out.println("Oficina registrada correctamente.");
                    }
                    else {
                        System.out.println("No se pudo registrar la oficina. Compruebe que el codigo no este repetido.");
                    }

                    break;
                }


                // Registrar dispositivo
                case 2: {

                    System.out.println("\nRegistrar Oficina");
                    System.out.println("1. Luminaria");
                    System.out.println("2. Climatizador");
                    System.out.println("3. Climatizador Inverter");
                    System.out.println("4. Sensor de humo");
                    System.out.println("5. Camara de seguridad");

                    int tipo = 0;

                    try {
                        System.out.print("Seleccione el tipo: ");
                        tipo = teclado.nextInt();
                        teclado.nextLine();

                    } catch (InputMismatchException e) {
                        System.out.println("Entrada invalida.");
                        teclado.nextLine();
                        break;
                    }

                    if (tipo < 1 || tipo > 5) {
                        System.out.println("Tipo de dispositivo invalido.");
                        break;
                    }

                    System.out.print("Codigo del dispositivo: ");
                    String codigo = teclado.nextLine();

                    if (codigo.isEmpty()) {
                        System.out.println("El codigo no puede estar vacio.");
                        break;
                    }

                    if (registro.buscarDispositivo(codigo) != null) {
                        System.out.println("Ya existe un dispositivo con ese codigo.");
                        break;
                    }

                    System.out.print("Codigo de oficina: ");
                    String codigoOficina = teclado.nextLine();

                    Oficina oficina = registro.buscarOficina(codigoOficina);

                    if (oficina == null) {
                        System.out.println("No se encontro la oficina.");
                        break;
                    }

                    double potencia = 0;

                    try {
                        System.out.print("Potencia nominal en watts: ");
                        potencia = teclado.nextDouble();
                        teclado.nextLine();

                    } catch (InputMismatchException e) {
                        System.out.println("Entrada invalida.");
                        teclado.nextLine();
                        break;
                    }

                    if (potencia <= 0 || Double.isNaN(potencia) || Double.isInfinite(potencia)) {
                        System.out.println("La potencia debe ser positiva y valida.");
                        break;
                    }

                    Dispositivo dispositivo = null;

                    switch (tipo) {

                        case 1:
                            dispositivo = new Luminaria(codigo, oficina, potencia);
                            break;

                        case 2:
                            dispositivo = new Climatizador(codigo, oficina, potencia);
                            break;

                        case 3:
                            dispositivo = new ClimatizadorInverter(codigo, oficina, potencia);
                            break;

                        case 4:
                            dispositivo = new SensorHumo(codigo, oficina, potencia);
                            break;

                        case 5:
                            dispositivo = new CamaraSeguridad(codigo, oficina, potencia);
                            break;
                    }

                    if (registro.registrarDispositivo(dispositivo)) {
                        System.out.println("Dispositivo registrado correctamente.");
                    }
                    else {
                        System.out.println("No se pudo registrar el dispositivo.");
                    }

                    break;
                }


                // Encender dispositivo
                case 3: {

                    System.out.println("\nEncender Dispositivo");
                    System.out.print("Codigo del dispositivo: ");
                    String codigo = teclado.nextLine();

                    if (torre.encenderDispositivo(codigo)) {
                        System.out.println("Dispositivo encendido correctamente.");
                    }
                    else {
                        System.out.println("No se pudo encender. Compruebe que exista, permita encenderse y no este encendido.");
                    }

                    break;
                }


                // Apagar dispositivo
                case 4: {

                    System.out.println("\nApagar Dispositivo");
                    System.out.print("Codigo del dispositivo: ");
                    String codigo = teclado.nextLine();

                    if (torre.apagarDispositivo(codigo)) {
                        System.out.println("Dispositivo apagado correctamente.");
                    }
                    else {
                        System.out.println("No se pudo apagar. Compruebe que exista, permita apagarse y no este apagado.");
                    }

                    break;
                }


                // Ajustar nivel
                case 5: {

                    System.out.println("\nAjustar Nivel");
                    System.out.print("Codigo del dispositivo: ");
                    String codigo = teclado.nextLine();

                    int nivel = 0;

                    try {
                        System.out.print("Nuevo nivel de intensidad: ");
                        nivel = teclado.nextInt();
                        teclado.nextLine();

                    } catch (InputMismatchException e) {
                        System.out.println("Entrada invalida.");
                        teclado.nextLine();
                        break;
                    }

                    if (torre.ajustarNivel(codigo, nivel)) {
                        System.out.println("Nivel ajustado correctamente.");
                    }
                    else {
                        System.out.println("No se pudo ajustar el nivel. Compruebe el estado y rango del dispositivo.");
                    }

                    break;
                }


                // Registrar lectura
                case 6: {

                    System.out.println("\nRegistar Lectura");
                    System.out.print("Codigo del dispositivo: ");
                    String codigo = teclado.nextLine();

                    double valor = 0;

                    try {
                        System.out.print("Valor de la lectura: ");
                        valor = teclado.nextDouble();
                        teclado.nextLine();

                    } catch (InputMismatchException e) {
                        System.out.println("Entrada invalida.");
                        teclado.nextLine();
                        break;
                    }

                    if (torre.registrarLectura(codigo, valor)) {
                        System.out.println("Lectura registrada correctamente.");
                    }
                    else {
                        System.out.println("No se pudo registrar la lectura. Compruebe el dispositivo y el rango permitido.");
                    }

                    break;
                }


                // Registrar movimiento
                case 7: {

                    System.out.println("\nRegistrar Movimiento");
                    System.out.print("Codigo del dispositivo: ");
                    String codigo = teclado.nextLine();

                    if (torre.registrarMovimiento(codigo)) {
                        System.out.println("Movimiento registrado correctamente.");
                    }
                    else {
                        System.out.println("No se pudo registrar el movimiento. Compruebe que sea una camara encendida.");
                    }

                    break;
                }


                // Avanzar hora
                case 8: {

                    torre.avanzarHora();

                    System.out.println("Se avanzo una hora de simulacion.");
                    System.out.println("Hora actual: " + torre.getHoraSimulacion());

                    if (torre.getHoraSimulacion() % 24 == 0) {
                        System.out.println("El dia ha terminado. Se generaron las facturas correspondientes.");
                    }

                    break;
                }


                // Atender alerta
                case 9: {

                    System.out.println("\nAtender Alerta");

                    Alerta alerta = registro.getBandeja().siguienteAlerta();

                    if (alerta == null) {
                        System.out.println("No hay alertas pendientes.");
                        break;
                    }

                    System.out.println("Alerta mas urgente:");
                    System.out.println(alerta);

                    if (torre.atenderAlerta()) {
                        System.out.println("Alerta atendida correctamente.");
                        System.out.println("Credito generado: Q" + String.format("%.2f", alerta.getRetraso() * alerta.getSeveridad().getCreditoHora()));
                    }
                    else {
                        System.out.println("No se pudo atender la alerta.");
                    }

                    break;
                }


                // Consultar oficinas
                case 10: {

                    System.out.println("\nConsultar Oficinas");

                    if (registro.getOficinas().isEmpty()) {
                        System.out.println("No hay oficinas registradas.");
                    }
                    else {
                        for (Oficina oficina : registro.getOficinas()) {
                            System.out.println("\n" + oficina);
                        }
                    }

                    break;
                }


                // Consultar dispositivo
                case 11: {

                    System.out.println("\nConsultar Dispositivo");
                    System.out.print("Codigo del dispositivo: ");
                    String codigo = teclado.nextLine();

                    Dispositivo dispositivo = registro.buscarDispositivo(codigo);

                    if (dispositivo == null) {
                        System.out.println("No se encontro el dispositivo.");
                    }
                    else {
                        System.out.println(dispositivo);
                    }

                    break;
                }


                // Reporte de dispositivos
                case 12: {

                    System.out.println("\nReporte de Dispositivos");
                    System.out.print("Codigo de oficina: ");
                    String codigo = teclado.nextLine();

                    torre.reporteDispositivos(codigo);

                    break;
                }


                // Reporte de alertas
                case 13: {

                    torre.reporteAlertas();
                    break;
                }


                // Reporte de facturas
                case 14: {

                    torre.reporteFacturas();
                    break;
                }


                // Salir
                case 15: {
                    continuar = false;
                    break;
                }
            }
        }

        teclado.close();
    }
}
